package com.srent.media;
import com.srent.audit.AuditService; import com.srent.common.ApiException; import com.srent.config.AppProperties; import com.srent.room.*; import com.srent.security.CurrentUser; import com.srent.storage.StorageService; import com.srent.user.UserRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/rooms/{roomId}") @RequiredArgsConstructor
public class MediaController {
    private final RoomRepository rooms; private final RoomVideoRepository videos; private final RoomImageRepository images; private final UserRepository users; private final StorageService storage; private final AppProperties props; private final AuditService audit;
    public record VideoRequest(@NotNull @DecimalMin("-90") @DecimalMax("90") BigDecimal latitude,@NotNull @DecimalMin("-180") @DecimalMax("180") BigDecimal longitude,@NotNull @DecimalMin("0") BigDecimal accuracyMeters,@NotNull Instant capturedAt,@NotBlank String contentType){}
    public record UploadResponse(UUID mediaId,String objectKey,String uploadUrl,Date expiresAt,BigDecimal distanceMeters,String warning){}
    public record CompleteRequest(@NotBlank String uploadToken){} public record VideoResponse(UUID id,RoomVideo.Status status,String url,Long sizeBytes,BigDecimal distanceMeters,String reviewNote,boolean gpsOnlyLocationCheck){static VideoResponse from(RoomVideo v,String url){return new VideoResponse(v.getId(),v.getStatus(),url,v.getSizeBytes(),v.getDistanceMeters(),v.getReviewNote(),true);}}
    @PostMapping("/video/upload-request") @PreAuthorize("hasRole('LANDLORD')") @Transactional public UploadResponse videoRequest(@PathVariable UUID roomId,@Valid @RequestBody VideoRequest q){var r=owned(roomId);validateVideo(q,r);String type=q.contentType().toLowerCase();if(!Set.of("video/mp4","video/webm","video/quicktime").contains(type))throw ApiException.badRequest("INVALID_VIDEO_TYPE","Chỉ hỗ trợ MP4, WebM hoặc QuickTime");double d=GeoDistance.haversineMeters(r.getProperty().getLatitude().doubleValue(),r.getProperty().getLongitude().doubleValue(),q.latitude().doubleValue(),q.longitude().doubleValue());if(d>props.getMedia().getGpsRadiusMeters())throw ApiException.badRequest("GPS_OUT_OF_RANGE","Thiết bị cách vị trí phòng %.1f m, vượt giới hạn %.0f m".formatted(d,props.getMedia().getGpsRadiusMeters()));String token=UUID.randomUUID().toString(),key="rooms/"+roomId+"/videos/"+UUID.randomUUID()+extension(type);var v=new RoomVideo();v.setRoom(r);v.setUploader(users.getReferenceById(CurrentUser.id()));v.setUploadToken(token);v.setObjectKey(key);v.setContentType(type);v.setDeviceLatitude(q.latitude());v.setDeviceLongitude(q.longitude());v.setGpsAccuracyMeters(q.accuracyMeters());v.setCapturedAt(q.capturedAt());v.setDistanceMeters(BigDecimal.valueOf(d).setScale(2,RoundingMode.HALF_UP));videos.save(v);var up=storage.presignedUpload(false,key,type);return new UploadResponse(v.getId(),key,up.url(),up.expiresAt(),v.getDistanceMeters(),"GPS chỉ kiểm tra vị trí thiết bị theo dữ liệu gửi lên, không chứng minh video là thật");}
    @PostMapping("/video/complete") @PreAuthorize("hasRole('LANDLORD')") @Transactional public VideoResponse complete(@PathVariable UUID roomId,@Valid @RequestBody CompleteRequest q){owned(roomId);var v=videos.findByUploadToken(q.uploadToken()).filter(x->x.getRoom().getId().equals(roomId)).orElseThrow(()->ApiException.notFound("Yêu cầu upload"));if(v.getStatus()!=RoomVideo.Status.UPLOADING)throw ApiException.conflict("UPLOAD_ALREADY_COMPLETED","Upload đã được hoàn tất");var m=storage.stat(false,v.getObjectKey());if(m.size()>props.getMedia().getMaxVideoSizeBytes())throw new ApiException(HttpStatus.PAYLOAD_TOO_LARGE,"VIDEO_TOO_LARGE","Video vượt dung lượng cho phép");if(!m.contentType().toLowerCase().startsWith("video/"))throw ApiException.badRequest("INVALID_VIDEO_TYPE","Tệp upload không phải video");v.setSizeBytes(m.size());v.setStatus(RoomVideo.Status.PENDING);audit.log(CurrentUser.id(),"VIDEO_SUBMITTED","ROOM_VIDEO",v.getId(),"distanceMeters="+v.getDistanceMeters());return VideoResponse.from(v,null);}
    @GetMapping("/video") public VideoResponse get(@PathVariable UUID roomId){var v=videos.findFirstByRoomIdAndStatusOrderByUpdatedAtDesc(roomId,RoomVideo.Status.APPROVED).orElseThrow(()->ApiException.notFound("Video đã duyệt"));return VideoResponse.from(v,storage.publicUrl(v.getObjectKey()));}
    public record ImageRequest(@NotBlank String contentType,@Min(0) int sortOrder){} public record ImageComplete(@NotBlank String objectKey,@NotBlank String contentType,@Min(0) int sortOrder){} public record ImageResponse(UUID id,String url,int sortOrder){}
    @PostMapping("/images/upload-request") @PreAuthorize("hasRole('LANDLORD')") @Transactional(readOnly=true) public StorageService.Upload imageRequest(@PathVariable UUID roomId,@Valid @RequestBody ImageRequest q){owned(roomId);if(!Set.of("image/jpeg","image/png","image/webp").contains(q.contentType()))throw ApiException.badRequest("INVALID_IMAGE_TYPE","Chỉ hỗ trợ JPEG, PNG, WebP");return storage.presignedUpload(false,"rooms/"+roomId+"/images/"+UUID.randomUUID()+extension(q.contentType()),q.contentType());}
    @PostMapping("/images/complete") @PreAuthorize("hasRole('LANDLORD')") @Transactional public ImageResponse imageComplete(@PathVariable UUID roomId,@Valid @RequestBody ImageComplete q){var r=owned(roomId);if(!q.objectKey().startsWith("rooms/"+roomId+"/images/"))throw ApiException.forbidden("Object key không thuộc phòng này");var m=storage.stat(false,q.objectKey());if(!m.contentType().startsWith("image/"))throw ApiException.badRequest("INVALID_IMAGE_TYPE","Tệp không phải ảnh");var i=new RoomImage();i.setRoom(r);i.setObjectKey(q.objectKey());i.setContentType(q.contentType());i.setSortOrder(q.sortOrder());images.save(i);return new ImageResponse(i.getId(),storage.publicUrl(i.getObjectKey()),i.getSortOrder());}
    @GetMapping("/images") public List<ImageResponse> imageList(@PathVariable UUID roomId){return images.findAllByRoomIdOrderBySortOrder(roomId).stream().map(i->new ImageResponse(i.getId(),storage.publicUrl(i.getObjectKey()),i.getSortOrder())).toList();}
    private Room owned(UUID id){var r=rooms.findById(id).orElseThrow(()->ApiException.notFound("Phòng"));if(!r.getProperty().getOwner().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Bạn không sở hữu phòng này");return r;}
    private void validateVideo(VideoRequest q,Room r){if(q.accuracyMeters().doubleValue()>props.getMedia().getMaxGpsAccuracyMeters())throw ApiException.badRequest("GPS_ACCURACY_POOR","Độ chính xác GPS không đạt yêu cầu");Instant now=Instant.now();if(q.capturedAt().isAfter(now.plusSeconds(30))||q.capturedAt().isBefore(now.minus(props.getMedia().getMaxLocationAge())))throw ApiException.badRequest("GPS_STALE","Vị trí GPS đã quá cũ hoặc thời gian không hợp lệ");}
    private static String extension(String t){return switch(t){case "video/mp4"->".mp4";case "video/webm"->".webm";case "video/quicktime"->".mov";case "image/jpeg"->".jpg";case "image/png"->".png";case "image/webp"->".webp";default->".bin";};}
}
